  anaer: {
    st: 'anaer', bean: 'cherryAn', m: 63,
    short: t('Anaerob', 'Anaerobic'),
    title: t('Anaerobe Fermentation & Carbonic Maceration', 'Anaerobic fermentation & carbonic maceration'),
    dur: t('Praxis oft 48–120 h; Studien 24–240 h', 'practice often 48–120 h; studies 24–240 h'),
    who: [t('Versiegelte Edelstahltanks mit Gärröhrchen', 'sealed steel tanks with airlocks'), t('CO₂-Spülung', 'CO₂ flushing'), t('Thermometer, pH-Meter', 'thermometer, pH meter'), t('Starterkulturen (optional)', 'starter cultures (optional)')],
    prax: t('Ganze Kirschen (Carbonic Maceration, aus dem Weinbau) oder entpulptes Pergament kommen in luftdicht verschlossene Tanks. CO₂ verdrängt den Sauerstoff – zugeführt oder selbst erzeugt («self-induced»). Danach wird je nach Rezept wie Natural getrocknet oder erst gewaschen. Kolumbien, Panama, Costa Rica und Brasilien experimentieren besonders viel.',
      'Whole cherries (carbonic maceration, borrowed from winemaking) or pulped parchment go into airtight tanks. CO₂ displaces oxygen – added or self-generated (“self-induced”). Afterwards they are dried like a natural or washed first, depending on the recipe. Colombia, Panama, Costa Rica and Brazil experiment most.'),
    params: [
      [t('Arabica-Studie', 'Arabica study'), t('Bestwerte bei 38 °C und 96 h (Food Chem. 2021)', 'best scores at 38 °C and 96 h (Food Chem. 2021)')],
      [t('Robusta (Conilon)', 'Robusta (Conilon)'), t('24–120 h, 18–38 °C; Score steigt mit Temperatur (Agronomy 2022)', '24–120 h, 18–38 °C; score rises with temperature (Agronomy 2022)')],
    ],
    chem: t('Ohne Sauerstoff fehlen Essigsäurebakterien; Hefen und Milchsäurebakterien bilden mehr Ester, höhere Alkohole und Milchsäure. In ganzen Kirschen kippt der Stoffwechsel der Frucht selbst von Atmung zu Gärung – intrazelluläre Fermentation wie beim Beaujolais. Längere Prozesse senken in Studien Zucker sowie 3- und 4-CQA (Chlorogensäuren); Ethylacetat und Amylacetat steigen. In selbst-induziert anaeroben Tanks dominierten Enterobakterien statt Milchsäurebakterien – anaerob heisst nicht automatisch kontrolliert.',
      'Without oxygen, acetic acid bacteria drop out; yeasts and lactic acid bacteria form more esters, higher alcohols and lactic acid. In whole cherries the fruit’s own metabolism switches from respiration to fermentation – intracellular fermentation as in Beaujolais. In studies, longer runs lower sugars and 3- and 4-CQA (chlorogenic acids) while ethyl acetate and amyl acetate rise. In self-induced anaerobic tanks enterobacteria dominated instead of lactic acid bacteria – anaerobic does not automatically mean controlled.'),
    cup: t('Intensive Frucht, Wein, Zimt, Joghurt, «boozy»; kann Herkunft und Varietät überdecken.', 'Intense fruit, wine, cinnamon, yoghurt, “boozy”; can mask origin and variety.'),
    risk: t('Übergärung, Lösungsmittelnoten (Ethylacetat), Inkonsistenz; Abgrenzung zu «infused» Kaffees mit Zusätzen verlangt Transparenz.', 'Over-fermentation, solvent notes (ethyl acetate), inconsistency; telling it apart from “infused” coffees with additives needs transparency.'),
  },
